What does this print (10-bit ADC value 512 mapped to 0..100)?
```c
#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
long map(long x, long in_min, long in_max, long out_min, long out_max){ return (x - in_min) * (out_max - out_min) / (in_max - in_min) + out_min; }
int main(void){ printf("%ld", map(512, 0, 1023, 0, 100)); }
```

What duty cycle (percent) is analogWrite value 256 with a 0..1023 range?
```c
#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
int main(void){ printf("%.1f", 256 * 100.0 / 1023); }
```

What does Arduino's map() give for a 10-bit reading of 512 mapped to 0..100?
```c
#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
long map(long x, long in_min, long in_max, long out_min, long out_max){ return (x - in_min) * (out_max - out_min) / (in_max - in_min) + out_min; }
int main(void){ printf("%ld %ld", map(512, 0, 1023, 0, 100), map(1023, 0, 1023, 0, 100)); }
```

